local Settings = dofile("storage/settings.lua")
local function store(value)
    return {value=value, readSetting=function(self) return self.value end, saveSetting=function(self, _, v) self.value=v end, flush=function(self) self.flushed=true end}
end
local s=store(nil); local cfg=assert(Settings.open(s)); assert(cfg.data.version == 3 and cfg.data.language == "en" and cfg.data.dns_mode=="auto" and cfg.data.source=="komiku" and cfg.data.profiles[1].id=="komiku")
assert(cfg.data.profiles[1].repository_url=="https://raw.githubusercontent.com/MRHRTZ/maru-manga-repository/refs/heads/master/metadata.json")
local empty_sources=assert(Settings.open(store({version=3,profiles={},auto_installed_source_ids={"komiku"}})))
assert(#empty_sources.data.profiles==0)
assert(cfg:setLanguage("ja")); assert(cfg:save()); assert(s.flushed and s.value.language == "ja")
local old=store({language="fr",source="mangadex"}); local migrated=Settings.open(old); assert(migrated.data.language == "fr" and migrated.data.source=="komiku" and migrated.data.profiles[1].id=="komiku")
local broken=store("broken"); local x=Settings.open(broken); assert(not x and broken.value == "broken")
local future=store({version=99}); assert(not Settings.open(future) and future.value.version == 99)
assert(not cfg:setLanguage("../bad")); assert(cfg.data.language == "ja")
print("Settings tests passed")

assert(cfg:addProfile({id="sample",name="Sample",base_url="https://example.org"})); assert(not cfg:addProfile({id="sample",name="Duplicate",base_url="https://example.org"})); assert(not cfg:addProfile({id="bad",name="Bad",base_url="http://example.org"}))

assert(cfg:setNetwork("30","4","Maru/1","/mnt/books",2,true)); assert(cfg.data.timeout==30 and cfg.data.retries==4 and cfg.data.ignore_ssl_certificates==true)
assert(cfg:setNetwork("30","4","Maru/1","/mnt/books",2,false)); assert(cfg.data.ignore_ssl_certificates==false)
assert(not cfg:setNetwork("0","4","Maru/1","/mnt/books")); assert(not cfg:setNetwork("10","3","ok","/a/../b")); assert(not cfg:setNetwork("30","3","ok","",2,"yes"))
assert(cfg:setDns("google") and cfg.data.dns_mode=="google")
assert(cfg:setDns("cloudflare") and cfg.data.dns_mode=="cloudflare")
assert(cfg:setDns("other","9.9.9.9") and cfg.data.dns_server=="9.9.9.9")
assert(not cfg:setDns("other","999.1.1.1"))
assert(cfg:setDns("auto") and cfg.data.dns_mode=="auto" and cfg.data.dns_server==nil)
local migrated=store({version=1,language="en"}); assert(Settings.open(migrated).data.dns_mode=="auto")
local old_komiku=assert(Settings.open(store({version=2,profiles={{id="komiku",name="Komiku",kind="komiku",base_url="https://komiku.org",api_url="https://api.komiku.org",languages={"id"},repository_url="builtin",repository_version=3}}})))
assert(old_komiku.data.version==3 and old_komiku.data.profiles[1].repository_url=="https://raw.githubusercontent.com/MRHRTZ/maru-manga-repository/refs/heads/master/metadata.json")
local legacy_source=store({version=2,source="mangago",profiles={{id="mangago",name="MangaGo",kind="mangago",base_url="https://mangamost.com",api_url="https://mangamost.com/api/v1",image_hosts={"mangamost.com"},enabled=false}}})
local source_migrated=assert(Settings.open(legacy_source)); assert(source_migrated.data.source=="mangamost" and source_migrated.data.profiles[1].id=="mangamost" and source_migrated.data.profiles[1].kind=="mangamost" and not source_migrated.data.profiles[1].enabled)
local legacy_mangago=store({version=2,source="mangago",profiles={{id="mangago",name="Mangago",kind="mangago",base_url="https://www.mangago.me",image_hosts={"www.mangago.me","img.mangago.me"},enabled=true}}})
local mangago_migrated=assert(Settings.open(legacy_mangago)); assert(mangago_migrated.data.profiles[1].base_url=="https://www.mangago.zone" and mangago_migrated.data.profiles[1].image_hosts[2]=="i1.mangapicgallery.com")
local westmanga=assert(Settings.open(store({version=2,profiles={{id="westmanga",name="WestManga",kind="westmanga",base_url="https://www.westmanga.shop",api_url="https://www.westmanga.shop/api/manga",image_hosts={"www.westmanga.shop","cdn.westmanga.shop","proxy.westmanga.shop"},enabled=true}}})))
assert(westmanga.data.profiles[1].id=="westmanga" and westmanga.data.profiles[1].kind=="westmanga")
assert(not Settings.open(store({version=2,profiles={{id="westmanga",name="WestManga",kind="westmanga",base_url="https://www.westmanga.shop",api_url="https://evil.example/api/manga",image_hosts={"evil.example"}}}})))

local corrupt=store({version=1,profiles={{id="x",name="X",base_url="https://example.org",image_hosts="bad"}}}); assert(not Settings.open(corrupt) and corrupt.value.profiles[1].image_hosts=="bad")
